import {state,api,esc,money,date,time,localDay,icon,badge,avatar,toast,modal,closeModal,refresh,navigate,memberName,empty,field,selectField,confirmAction,imageDataUrl} from './core.js';
import {renderModule,handleModuleAction,afterModuleRender} from './modules.js';

const roles={dueno:'Dueño',administrador:'Administrador',recepcionista:'Recepción',profesor:'Profesor',contador:'Contador'};
const adminRoles=['dueno','administrador'];
const deskRoles=[...adminRoles,'recepcionista'];
const financeRoles=[...deskRoles,'contador'];
const allRoles=Object.keys(roles);
const pages={
inicio:{title:'Vista general',sub:'Todo lo que necesitás para acompañar a tu comunidad.',icon:'grid',roles:allRoles},
socios:{title:'Socios',sub:'Cada persona, una historia. Toda su información en un solo lugar.',icon:'users',roles:allRoles},
accesos:{title:'Control de acceso',sub:'Una bienvenida simple. Un registro de cada entrenamiento.',icon:'door',roles:deskRoles},
vencimientos:{title:'Cuotas y vencimientos',sub:'Anticipate a las renovaciones y mantené a tus socios al día.',icon:'calendar',roles:financeRoles},
planes:{title:'Planes y membresías',sub:'Una propuesta para cada forma de entrenar.',icon:'card',roles:financeRoles},
caja:{title:'Caja y movimientos',sub:'Los números de tu gimnasio, claros y ordenados.',icon:'wallet',roles:financeRoles},
productos:{title:'Productos y stock',sub:'Controlá tus productos y anticipá las próximas reposiciones.',icon:'box',roles:financeRoles},
ventas:{title:'Punto de venta',sub:'Sumá productos, elegí el medio de pago y registrá la venta.',icon:'cart',roles:financeRoles},
profesores:{title:'Profesores',sub:'El equipo que hace posible cada entrenamiento.',icon:'user',roles:[...deskRoles,'profesor']},
clases:{title:'Clases y reservas',sub:'Organizá la agenda y encontrá un lugar para cada socio.',icon:'calendar',roles:[...deskRoles,'profesor']},
rutinas:{title:'Rutinas',sub:'Entrenamientos pensados para cada objetivo.',icon:'dumbbell',roles:[...deskRoles,'profesor']},
progreso:{title:'Progreso físico',sub:'Cada pequeño avance también cuenta.',icon:'activity',roles:[...adminRoles,'profesor']},
asistencia:{title:'Asistencia',sub:'Conocé los hábitos de tu comunidad y acompañá su constancia.',icon:'chart',roles:allRoles},
comunicaciones:{title:'Comunicaciones',sub:'Mensajes que acercan a tu gimnasio y a tus socios.',icon:'message',roles:deskRoles},
reportes:{title:'Reportes e inteligencia',sub:'Transformá tus registros en mejores decisiones.',icon:'chart',roles:[...adminRoles,'contador']},
configuracion:{title:'Configuración',sub:'Tu gimnasio, a tu manera.',icon:'settings',roles:adminRoles},
auditoria:{title:'Registro de actividad',sub:'Transparencia y trazabilidad en cada operación.',icon:'shield',roles:[...adminRoles,'contador']}
};
let memberSearch='',memberFilter='todos',memberPage=0,accessFilter='todos',chartDays=7,communicationType='recordatorio',dashboardAlert='due';
const pageSize=10;
let accessResult=null,accessReset=null;
const canDesk=()=>deskRoles.includes(state.user.role);
const isAdmin=()=>adminRoles.includes(state.user.role);
const data=()=>state.data;
const byDate=arr=>[...arr].sort((a,b)=>String(b.date||b.createdAt).localeCompare(String(a.date||a.createdAt)));
const todayCheckins=()=>data().checkins.filter(c=>localDay(c.date)===data().today);
const birthday=m=>m.birthDate?.slice(5)===data().today.slice(5);
const active=m=>m.status==='activo';
const dueSoon=()=>data().members.filter(m=>m.state!=='baja'&&m.state!=='suspendido'&&m.daysLeft>=0&&m.daysLeft<=5).sort((a,b)=>a.daysLeft-b.daysLeft);
const statusBadge=m=>badge(m.status==='activo'?(m.daysLeft<=5?'Vence pronto':'Activo'):{vencido:'Vencido',suspendido:'Suspendido',baja:'Baja'}[m.status]||m.status,m.status==='activo'?(m.daysLeft<=5?'amber':'green'):m.status==='vencido'?'red':'neutral');
const addDays=(value,n)=>{const d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
const memberCell=m=>`<button class="member-cell" data-action="member-detail" data-id="${esc(m.id)}">${avatar(m)}<span><strong>${esc(m.name)}</strong><small>Socio #${esc(m.number)}</small></span></button>`;
const logo=()=>`<span class="brand-mark"><svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M6 31 17 8h7l11 23H26l-6-14-6 14Z" fill="currentColor"/><path d="m17 27 4-7 6 11H15Z" fill="#ffd8c9"/></svg></span><span class="brand-word">ANVERSOL<small>GYM MANAGEMENT</small></span>`;
function renderShell(){const d=data(),p=pages[state.route];const groups=[['PRINCIPAL',['inicio','socios','accesos','vencimientos']],['ADMINISTRACIÓN',['planes','caja','productos','ventas']],['ENTRENAMIENTO',['profesores','clases','rutinas','progreso','asistencia']],['CRECIMIENTO',['comunicaciones','reportes']]];const fullDate=new Date(d.today+'T12:00:00').toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const alerts=dueSoon().length+d.members.filter(birthday).length;document.getElementById('app').innerHTML=`
<a class="skip-link" href="#main">Saltar al contenido</a><div class="nav-overlay" data-action="toggle-nav"></div>
<aside class="sidebar"><a href="#inicio" class="brand" data-route="inicio" aria-label="Anversol inicio">${logo()}</a><div class="gym-selector"><span class="gym-tile">${icon('dumbbell',19)}</span><span><strong>${esc(d.settings.gymName||'Anversol Gym')}</strong><small>Sede principal</small></span>${icon('down',15)}</div>
<nav aria-label="Navegación principal">${groups.map(([title,routes])=>{const available=routes.filter(r=>pages[r].roles.includes(state.user.role));return available.length?`<div class="nav-group"><div class="nav-label">${title}</div>${available.map(r=>`<a class="nav-item ${state.route===r?'active':''}" href="#${r}" data-route="${r}" ${state.route===r?'aria-current="page"':''}>${icon(pages[r].icon,19)}<span>${r==='inicio'?'Vista general':r==='vencimientos'?'Vencimientos':r==='planes'?'Planes y membresías':r==='caja'?'Caja y gastos':r==='ventas'?'Ventas':r==='progreso'?'Progreso físico':r==='reportes'?'Reportes':r==='accesos'?'Control de acceso':pages[r].title}</span>${r==='vencimientos'&&dueSoon().length?`<b class="nav-count">${dueSoon().length}</b>`:''}</a>`).join('')}</div>`:'';}).join('')}</nav>
<div class="sidebar-bottom">${pages.configuracion.roles.includes(state.user.role)?`<a href="#configuracion" data-route="configuracion" class="nav-item ${state.route==='configuracion'?'active':''}">${icon('settings',18)}Configuración</a>`:''}${pages.auditoria.roles.includes(state.user.role)?`<a href="#auditoria" data-route="auditoria" class="nav-item ${state.route==='auditoria'?'active':''}">${icon('shield',18)}Actividad del sistema</a>`:''}<div class="local-status"><i class="status-dot"></i><span>Servidor local conectado<small>${state.access?.lan?esc(state.access.url.replace(/^https?:\/\//,'')):'Listo para trabajar sin Internet'}</small></span></div></div></aside>
<div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="toggle-nav" aria-label="Abrir menú">${icon('menu')}</button><div class="breadcrumb">Tu gimnasio <span>/</span> <strong>${esc(p.title)}</strong></div><div class="topbar-right">${d.settings.demo?'<span class="demo-label">Datos de demostración</span>':''}<button class="icon-btn notification-btn ${alerts?'has-alerts':''}" data-route="${financeRoles.includes(state.user.role)?'vencimientos':'asistencia'}" aria-label="Ver alertas">${icon('bell')}<i></i></button><div class="topbar-divider"></div><button class="profile-button" data-action="profile">${avatar(state.user)}<span><strong>${esc(state.user.name)}</strong><small>${esc(roles[state.user.role])}</small></span>${icon('down',14)}</button></div></header>
<main id="main"><div class="page-heading"><div><div class="eyebrow">${state.route==='inicio'?`${icon('sun',14)} UN NUEVO DÍA PARA CRECER`:'ANVERSOL · SEDE PRINCIPAL'}</div><h1>${state.route==='inicio'?'Tu gimnasio, en movimiento.':esc(p.title)}</h1><p>${esc(p.sub)}</p></div><div class="page-actions">${state.route==='inicio'?`<span class="date-display">${icon('calendar',16)}${esc(fullDate)}</span>`:''}${state.route==='socios'&&canDesk()?`<button class="btn btn-primary" data-action="member-new">${icon('plus',18)}Nuevo socio</button>`:''}${state.route==='accesos'?`<button class="btn btn-secondary" data-action="kiosk">${icon('fingerprint',18)}Pantalla de recepción</button>`:''}</div></div><div id="page-content"></div><footer class="page-footer"><span>ANVERSOL <b>GYM</b></span><span>Más tiempo para tu comunidad.</span><span>${icon('lock',12)} Tus datos, en tu gimnasio</span></footer></main></div>`;
const content=document.getElementById('page-content');content.innerHTML=({inicio:dashboard,socios:membersPage,accesos:accessPage,vencimientos:expiryPage,asistencia:attendancePage,comunicaciones:communicationsPage}[state.route]||(()=>renderModule(state.route)))();bindPage();afterModuleRender(state.route);}

function metric(label,value,detail,ico,tone='peach'){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon(ico,20)}</span></div><div class="stat-value">${value}</div><div class="stat-detail">${detail}</div></article>`;}
function trend(current,previous){if(!previous)return `<span class="muted">${current?'Actividad registrada':'Sin actividad'} en el período</span>`;const percent=Math.round((current-previous)/previous*100);return `<span class="trend ${percent>=0?'positive':'negative'}">${percent>=0?'+':''}${percent}%</span><span class="muted"> vs. período anterior</span>`;}
function dashboard(){const d=data(),admitted=todayCheckins().filter(c=>c.allowed),inside=admitted.filter(c=>!c.checkoutAt),activeMembers=d.members.filter(active),expired=d.members.filter(m=>m.status==='vencido');const todayPayments=d.payments.filter(p=>localDay(p.date)===d.today),weekNew=d.members.filter(m=>m.joinedAt>=addDays(d.today,-6));const showMoney=financeRoles.includes(state.user.role);const todayClasses=d.classes.filter(c=>c.date===d.today).sort((a,b)=>a.time.localeCompare(b.time));return `
<section class="stats-grid">${metric('Socios activos',activeMembers.length,`<span class="positive">${icon('up',13)} ${weekNew.length} nuevos</span><span class="muted"> en los últimos 7 días</span>`,'users')}${metric('Ingresos de hoy',admitted.length,`<span class="live-dot"></span><span>${inside.length} personas dentro del gimnasio</span>`,'door','blue')}${metric(showMoney?'Recaudación de hoy':'Clases de hoy',showMoney?money(todayPayments.reduce((a,p)=>a+p.amount,0)):todayClasses.length,showMoney?`<span class="muted">${todayPayments.length} cuotas cobradas hoy</span>`:'Sesiones programadas','wallet','mint')}${metric('Vencimientos próximos',dueSoon().length,`<span class="amber-text">Próximos 5 días</span><span class="muted"> · ${expired.length} vencidos</span>`,'calendar','lavender')}</section>
<div class="dashboard-main"><section class="card attendance-card"><div class="card-head"><div><h2>Así se mueve tu comunidad</h2><p class="muted">Ingresos al gimnasio</p></div><select id="chart-period" aria-label="Período de asistencia"><option value="7" ${chartDays===7?'selected':''}>Últimos 7 días</option><option value="30" ${chartDays===30?'selected':''}>Últimos 30 días</option></select></div>${attendanceChart()}<div class="chart-bottom"><span><i class="legend-dot"></i>Ingresos habilitados</span><a href="#asistencia" data-route="asistencia">Ver asistencia ${icon('arrow',15)}</a></div></section>
<section class="quick-card"><div class="quick-decoration">${icon('dumbbell',130)}</div><span class="eyebrow">TODO A MANO</span><h2>Menos gestión.<br>Más movimiento.</h2><p>Tu día a día, un poco más simple.</p><div class="quick-actions">${canDesk()?`<button data-action="payment">${icon('wallet',20)}<span>Registrar un pago</span>${icon('arrow',18)}</button><button data-action="member-new">${icon('users',20)}<span>Sumar un nuevo socio</span>${icon('arrow',18)}</button><button data-route="accesos">${icon('door',20)}<span>Registrar un ingreso</span>${icon('arrow',18)}</button>`:`<button data-route="socios">${icon('users',20)}<span>Consultar socios</span>${icon('arrow',18)}</button><button data-route="${state.user.role==='profesor'?'rutinas':'reportes'}">${icon('chart',20)}<span>${state.user.role==='profesor'?'Ver rutinas':'Consultar reportes'}</span>${icon('arrow',18)}</button>`}</div><span class="quick-footer"><i></i>Un gran entrenamiento empieza acá.</span></section></div>
<div class="dashboard-lower"><section class="card"><div class="card-head"><div><h2>Últimos ingresos</h2><p class="muted">La comunidad no se detiene</p></div>${badge('Hoy','green')}</div>${accessTable(byDate(todayCheckins()).slice(0,5),true)}<a class="card-link" href="#${canDesk()?'accesos':'asistencia'}" data-route="${canDesk()?'accesos':'asistencia'}">Ver todos los ingresos ${icon('arrow',16)}</a></section>
<section class="card due-card"><div class="card-head"><div><h2>Para tener en cuenta</h2><p class="muted">Un pequeño recordatorio hace la diferencia</p></div><span class="soft-icon peach">${icon('bell',20)}</span></div><div class="alert-tabs"><button type="button" class="${dashboardAlert==='due'?'selected':''}" data-action="alert-tab" data-id="due">Por vencer <b>${dueSoon().length}</b></button><button type="button" class="${dashboardAlert==='birthday'?'selected':''}" data-action="alert-tab" data-id="birthday">Cumpleaños <b>${d.members.filter(birthday).length}</b></button></div><div class="due-list">${(dashboardAlert==='birthday'?d.members.filter(birthday).slice(0,5):dueSoon().slice(0,3)).map(m=>`<div class="due-row">${memberCell(m)}<div>${dashboardAlert==='birthday'?badge('Hoy','green'):badge(m.daysLeft===0?'Vence hoy':`En ${m.daysLeft} día${m.daysLeft===1?'':'s'}`,'amber')}${canDesk()?`<button class="icon-btn" data-action="${dashboardAlert==='birthday'?'whatsapp-birthday':'whatsapp'}" data-id="${esc(m.id)}" aria-label="Mensaje para ${esc(m.name)}">${icon('message',18)}</button>`:''}</div></div>`).join('')||empty(dashboardAlert==='birthday'?'Hoy no hay cumpleaños.':'No hay cuotas por vencer en los próximos días.')}</div><a href="#${financeRoles.includes(state.user.role)?'vencimientos':'socios'}" data-route="${financeRoles.includes(state.user.role)?'vencimientos':'socios'}" class="card-link">Ver socios ${icon('arrow',16)}</a></section></div>
<section class="card daily-classes"><div class="card-head"><div><h2>La agenda de hoy</h2><p class="muted">Energía compartida, objetivos en común</p></div>${pages.clases.roles.includes(state.user.role)?'<a href="#clases" data-route="clases">Ver agenda completa →</a>':''}</div><div class="class-strip">${todayClasses.slice(0,4).map((c,i)=>{const reserved=d.reservations.filter(r=>r.classId===c.id).length;return `<div class="class-mini"><span class="class-time">${esc(c.time)}</span><div><strong>${esc(c.name)}</strong><small>${esc(d.teachers.find(t=>t.id===c.teacherId)?.name||'Sin profesor')}</small></div><span class="class-spots">${reserved}/${c.capacity}<small>reservas</small></span></div>`;}).join('')||empty('Hoy no hay clases programadas.')}</div></section>`;}
function attendanceChart(){const d=data();const values=Array.from({length:chartDays},(_,i)=>{const day=addDays(d.today,i-chartDays+1);return {day,value:d.checkins.filter(c=>c.allowed&&localDay(c.date)===day).length};});const total=values.reduce((a,x)=>a+x.value,0),previous=d.checkins.filter(c=>c.allowed&&localDay(c.date)>=addDays(d.today,-2*chartDays+1)&&localDay(c.date)<values[0].day).length;const max=Math.max(4,...values.map(v=>v.value));const step=Math.ceil(max/4);const chartMax=step*4;const W=700,H=175;const points=values.map((v,i)=>[35+i*(W-55)/(values.length-1),H-15-(v.value/chartMax)*(H-35)]);const line=points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');return `<div class="chart-summary"><strong>${total}</strong><span>visitas</span><div>${trend(total,previous)}</div></div><div class="attendance-chart"><svg viewBox="0 0 ${W} ${H+30}" role="img" aria-label="Asistencia: ${values.map(v=>`${date(v.day)}: ${v.value}`).join(', ')}"><defs><linearGradient id="area-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#ef7b61" stop-opacity=".23"/><stop offset="1" stop-color="#ef7b61" stop-opacity=".01"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const y=H-15-i*(H-35)/4;return `<line x1="35" y1="${y}" x2="${W-20}" y2="${y}" stroke="#eae9e7" stroke-dasharray="3 5"/><text x="0" y="${y+4}" class="chart-label">${step*i}</text>`;}).join('')}<path d="${line} L${W-20},${H-15} L35,${H-15} Z" fill="url(#area-fill)"/><path d="${line}" stroke="#ed775b" fill="none" stroke-width="2.8" stroke-linejoin="round"/>${points.map((p,i)=>chartDays<=7?`<circle cx="${p[0]}" cy="${p[1]}" r="4" stroke="#fff" stroke-width="2" fill="#ed775b"><title>${date(values[i].day)}: ${values[i].value} ingresos</title></circle>`:'').join('')}${values.map((v,i)=>i===0||i===values.length-1||i%(chartDays===7?1:5)===0?`<text x="${points[i][0]}" y="${H+13}" text-anchor="middle" class="chart-label">${chartDays===7?new Date(v.day+'T12:00:00').toLocaleDateString('es-AR',{weekday:'short'}):v.day.slice(8)}</text>`:'').join('')}</svg></div>`;}
function accessTable(list,compact=false){if(!list.length)return empty('Todavía no hay ingresos registrados.');return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Socio</th>${compact?'':'<th>Fecha</th>'}<th>Ingreso</th><th>Estado</th>${compact?'':'<th>Salida</th><th></th>'}</tr></thead><tbody>${list.map(c=>{const m=data().members.find(m=>m.id===c.memberId)||{id:'',name:'Socio',number:'—'};return `<tr><td>${memberCell(m)}</td>${compact?'':`<td>${date(c.date)}</td>`}<td class="mono">${time(c.date)}</td><td>${badge(c.allowed?'Habilitado':'Denegado',c.allowed?'green':'red')}</td>${compact?'':`<td>${c.checkoutAt?time(c.checkoutAt):c.allowed?'Dentro':'—'}</td><td>${c.allowed&&!c.checkoutAt&&canDesk()?`<button class="btn btn-sm btn-secondary" data-action="checkout" data-id="${c.id}">Salida</button>`:esc(c.allowed?'':c.reason)}</td>`}</tr>`;}).join('')}</tbody></table></div>`;}

function membersPage(){return `<div class="member-summary"><button class="summary-pill ${memberFilter==='todos'?'selected':''}" data-action="member-filter" data-id="todos">Todos los socios <b>${data().members.length}</b></button>${[['activo','Activos'],['vencido','Vencidos'],['suspendido','Suspendidos'],['baja','Bajas']].map(([v,t])=>`<button class="summary-pill ${memberFilter===v?'selected':''}" data-action="member-filter" data-id="${v}">${t}<b>${data().members.filter(m=>m.status===v).length}</b></button>`).join('')}</div><section class="card"><div class="toolbar"><div class="search-field">${icon('search',18)}<input id="member-search" placeholder="Buscar por nombre, DNI, teléfono o número…" aria-label="Buscar socios" value="${esc(memberSearch)}"></div><div class="toolbar-actions">${financeRoles.includes(state.user.role)?`<a class="btn btn-secondary" href="/api/export?type=members">${icon('download',17)}Exportar CSV</a>`:''}</div></div><div id="members-results">${memberTable()}</div></section>`;}
function memberTable(){const query=memberSearch.toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');const members=data().members.filter(m=>(memberFilter==='todos'||m.status===memberFilter)&&[m.name,m.dni,m.phone,m.whatsapp,m.email,m.number].some(v=>String(v||'').toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(query)));memberPage=Math.min(memberPage,Math.max(0,Math.ceil(members.length/pageSize)-1));return members.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Socio</th><th>DNI</th><th>Plan</th><th>Vencimiento</th><th>Estado</th><th></th></tr></thead><tbody>${members.slice(memberPage*pageSize,(memberPage+1)*pageSize).map(m=>`<tr><td>${memberCell(m)}</td><td class="muted mono">${esc(m.dni)}</td><td>${esc(m.planName||data().plans.find(p=>p.id===m.planId)?.name||'Sin plan')}</td><td>${date(m.expiresAt)}</td><td>${statusBadge(m)}</td><td><button class="icon-btn" data-action="member-detail" data-id="${esc(m.id)}" aria-label="Ver ficha de ${esc(m.name)}">${icon('chevron',18)}</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${memberPage*pageSize+1}–${Math.min((memberPage+1)*pageSize,members.length)} de ${members.length} socios</span><div><button class="btn btn-sm btn-secondary" data-action="member-prev" ${memberPage===0?'disabled':''}>Anterior</button><span>${memberPage+1} / ${Math.ceil(members.length/pageSize)}</span><button class="btn btn-sm btn-secondary" data-action="member-next" ${(memberPage+1)*pageSize>=members.length?'disabled':''}>Siguiente</button></div></div>`:empty('No encontramos socios con esa búsqueda.');}

function accessPage(){const list=byDate(todayCheckins()).filter(c=>accessFilter==='todos'||(accessFilter==='dentro'?c.allowed&&!c.checkoutAt:!c.allowed));return `<div class="access-layout"><section class="card access-entry"><div class="access-entry-head"><span class="access-symbol">${icon('fingerprint',38)}</span><p class="access-clock" id="access-clock"></p><h2>Una nueva visita.<br>Un nuevo objetivo.</h2><p>Identificá al socio para registrar su ingreso.</p><span class="inside-chip">${todayCheckins().filter(c=>c.allowed&&!c.checkoutAt).length} personas dentro ahora</span></div><form id="access-form"><label class="field"><span>DNI o número de socio</span><input id="access-identifier" name="identifier" placeholder="Ej. 35123456" autocomplete="off" inputmode="numeric" required autofocus></label>${selectField('Identificación','method',[{value:'manual',label:'DNI / número de socio'},{value:'qr',label:'Código de lector QR'}])}<button class="btn btn-primary full" type="submit">${icon('door',18)}Registrar ingreso</button></form><div class="reader-note">${icon('fingerprint',18)}<span>Lector de huellas pendiente de instalación.<br>El ingreso manual está disponible.</span></div></section><section class="card access-result" id="access-result">${accessResultHtml()}</section></div><section class="card"><div class="card-head"><div><h2>Movimiento de hoy</h2><p class="muted">${todayCheckins().filter(c=>c.allowed).length} ingresos · ${todayCheckins().filter(c=>c.allowed&&!c.checkoutAt).length} personas dentro</p></div><select id="access-filter" aria-label="Filtrar ingresos">${[['todos','Todos los registros'],['dentro','Dentro del gimnasio'],['denegados','Accesos denegados']].map(([v,t])=>`<option value="${v}" ${v===accessFilter?'selected':''}>${t}</option>`).join('')}</select></div>${accessTable(list)}</section>`;}
function accessResultHtml(){if(!accessResult)return `<div class="waiting-pulse">${icon('door',40)}</div><span class="eyebrow">RECEPCIÓN ANVERSOL</span><h2>Listos para recibirte.</h2><p class="muted">Ingresá un DNI o escaneá el código del socio.<br>Su estado de acceso aparecerá acá.</p><span class="badge badge-green"><i></i>Control de acceso disponible</span>`;const r=accessResult,m=r.member;return `<div class="checkin-result ${r.allowed?'allowed':'denied'}">${avatar(m)}<span class="eyebrow">${r.allowed?'¡BIENVENIDO!':'REVISAR ACCESO'}</span><h2>${esc(m.name)}</h2>${badge(r.allowed?'ACCESO HABILITADO':'ACCESO DENEGADO',r.allowed?'green':'red')}<p>${esc(r.reason||'Que tengas un gran entrenamiento.')}</p><div class="access-meta"><span>Plan<strong>${esc(m.planName||data().plans.find(p=>p.id===m.planId)?.name||'Sin plan')}</strong></span><span>Vencimiento<strong>${date(m.expiresAt)}</strong></span></div>${birthday(m)?'<p>🎂 ¡Hoy es tu cumpleaños!</p>':''}${m.medicalExpiresAt&&m.medicalExpiresAt<data().today?'<p class="amber-text">Apto físico vencido</p>':''}${!r.allowed&&m.status==='vencido'&&data().settings.allowExpiredOverride?`<button class="btn btn-secondary" data-action="access-override" data-id="${esc(m.id)}">Autorizar ingreso excepcional</button>`:''}${!r.allowed&&canDesk()&&(m.status==='vencido'||m.state==='baja')?`<button class="btn btn-primary" data-action="payment" data-id="${esc(m.id)}">Renovar cuota</button>`:''}</div>`;}

function expiryPage(){const d=data(),expired=d.members.filter(m=>m.status==='vencido'),today=d.members.filter(m=>m.daysLeft===0&&m.state==='activo'),tomorrow=d.members.filter(m=>m.daysLeft===1&&m.state==='activo');const list=[...expired,...dueSoon()].sort((a,b)=>String(a.expiresAt).localeCompare(String(b.expiresAt)));return `<section class="stats-grid">${metric('Cuotas vencidas',expired.length,'Membresías pendientes de renovación','alert','peach')}${metric('Vencen hoy',today.length,date(d.today),'calendar','sand')}${metric('Vencen mañana',tomorrow.length,date(addDays(d.today,1)),'clock','blue')}${metric('Próximos 5 días',dueSoon().length,'Incluye las cuotas que vencen hoy','card','lavender')}</section><section class="card"><div class="card-head"><div><h2>Que nadie se quede sin entrenar</h2><p class="muted">Contactá a tus socios o registrá su renovación.</p></div>${canDesk()?`<button class="btn btn-primary" data-action="payment">${icon('plus',17)}Registrar pago</button>`:''}</div>${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Socio</th><th>Plan</th><th>Vencimiento</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${list.map(m=>`<tr><td>${memberCell(m)}</td><td>${esc(m.planName||'Sin plan')}</td><td>${date(m.expiresAt)}</td><td>${statusBadge(m)}</td><td><div class="row-actions">${canDesk()?`<button class="btn btn-sm btn-secondary" data-action="whatsapp" data-id="${m.id}">${icon('message',15)}Recordar</button><button class="btn btn-sm btn-primary" data-action="payment" data-id="${m.id}">Cobrar cuota</button>`:'—'}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Todas las membresías están al día.')}</section>`;}

function attendancePage(){const d=data(),admitted=d.checkins.filter(c=>c.allowed),period=admitted.filter(c=>localDay(c.date)>=addDays(d.today,-29));const ranked=d.members.map(m=>({...m,visits:period.filter(c=>c.memberId===m.id).length})).sort((a,b)=>b.visits-a.visits);const absent=d.members.filter(m=>m.state==='activo'&&(!m.lastCheckin?m.joinedAt<=addDays(d.today,-15):localDay(m.lastCheckin)<=addDays(d.today,-15)));const hours=Array.from({length:24},(_,h)=>({hour:h,count:period.filter(c=>Number(time(c.date).split(':')[0])===h).length}));const peak=hours.reduce((a,b)=>a.count>=b.count?a:b);return `<section class="stats-grid">${metric('Visitas en 30 días',period.length,'Ingresos habilitados registrados','door')}${metric('Promedio diario',(period.length/30).toFixed(1),'Últimos 30 días calendario','chart','blue')}${metric('Horario con más visitas',peak.count?`${String(peak.hour).padStart(2,'0')}:00`:'—',`${peak.count} ingresos en esa franja`,'clock','mint')}${metric('Sin asistir hace 15 días',absent.length,'Socios para volver a conectar','heart','lavender')}</section><section class="card"><div class="card-head"><div><h2>La constancia, a la vista</h2><p class="muted">Ingresos diarios al gimnasio</p></div><select id="chart-period" aria-label="Período de asistencia"><option value="7" ${chartDays===7?'selected':''}>Últimos 7 días</option><option value="30" ${chartDays===30?'selected':''}>Últimos 30 días</option></select></div>${attendanceChart()}</section><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Los más constantes</h2><p class="muted">Entrenamientos en los últimos 30 días</p></div>${icon('sparkles')}</div><div class="rank-list">${ranked.filter(m=>m.visits>0).slice(0,8).map((m,i)=>`<div class="rank-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span>${memberCell(m)}<strong>${m.visits}<small>visitas</small></strong></div>`).join('')||empty('Los próximos ingresos aparecerán acá.')}</div></section><section class="card"><div class="card-head"><div><h2>Los extrañamos por acá</h2><p class="muted">Sin visitas registradas en los últimos 15 días</p></div>${icon('heart')}</div><div class="due-list">${absent.slice(0,15).map(m=>`<div class="due-row">${memberCell(m)}${canDesk()?`<button class="btn btn-sm btn-secondary" data-action="whatsapp-recovery" data-id="${m.id}">${icon('message',16)}Contactar</button>`:`<span class="muted">${m.lastCheckin?date(m.lastCheckin):'Sin visitas'}</span>`}</div>`).join('')||empty('Tu comunidad se mantiene en movimiento.')}</div></section></div><section class="card"><div class="card-head"><h2>Historial de ingresos</h2>${financeRoles.includes(state.user.role)?'<a class="btn btn-secondary" href="/api/export?type=checkins">Exportar CSV</a>':''}</div>${accessTable(byDate(d.checkins).slice(0,100))}<p class="table-note">Últimos 100 registros. El archivo exportado incluye el historial completo.</p></section>`;}

const messageTemplates={recordatorio:'Recordatorio de cuota',bienvenida:'Bienvenida',recuperacion:'Volver a entrenar',cumpleanos:'Cumpleaños',promocion:'Promociones',horario:'Cambio de horario'};
function messageFor(m,type){const name=m.name.split(' ')[0],gym=data().settings.gymName||'Anversol Gym';return {recordatorio:`Hola ${name} 👋 Te escribimos desde ${gym}. Tu membresía ${m.daysLeft<0?'venció':'vence'} el ${date(m.expiresAt)}. Podés acercarte a recepción para renovarla. ¡Te esperamos! 💪`,bienvenida:`¡Bienvenido/a a ${gym}, ${name}! 💪 Nos alegra acompañarte en tus objetivos. Acercate a recepción si necesitás ayuda.`,recuperacion:`¡Hola ${name}! En ${gym} te extrañamos. ¿Volvemos a entrenar? Escribinos y te ayudamos a retomar. 💪`,cumpleanos:`🎂 ¡Feliz cumpleaños, ${name}! Todo el equipo de ${gym} te desea un excelente día. ¡A seguir cumpliendo objetivos! 💪`,promocion:`Hola ${name} 👋 Tenemos novedades para vos en ${gym}. Consultá en recepción los planes y promociones disponibles.`,horario:`Hola ${name}, te escribimos de ${gym} para avisarte un cambio en los horarios. [Completá acá el nuevo horario antes de enviar].`}[type]||'';}
function communicationsPage(){const birthdays=data().members.filter(birthday);return `<div class="message-banner"><span class="soft-icon mint">${icon('message',28)}</span><div><h2>Una comunidad también se entrena cerca.</h2><p>Elegí un mensaje, revisalo y abrilo en WhatsApp para enviarlo.</p></div>${badge('Envío manual','green')}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Preparar un mensaje</h2><p class="muted">Los mensajes se abren como borradores.</p></div></div><form id="message-form" class="padded-form">${selectField('Socio','memberId',data().members.map(m=>({value:m.id,label:m.name})))}${selectField('Tipo de mensaje','type',Object.entries(messageTemplates).map(([value,label])=>({value,label})),communicationType)}<label class="field"><span>Mensaje</span><textarea name="message" rows="7">${esc(data().members.length?messageFor(data().members[0],communicationType):'')}</textarea></label><button class="btn btn-primary" type="submit">${icon('message',18)}Abrir en WhatsApp</button><p class="muted small">WhatsApp requiere Internet. El envío lo confirmás vos.</p></form></section><section class="card"><div class="card-head"><div><h2>Cumpleaños de hoy</h2><p class="muted">Un saludo que suma</p></div><span class="soft-icon peach">${icon('gift',24)}</span></div>${birthdays.map(m=>`<div class="due-row">${memberCell(m)}<button class="btn btn-sm btn-secondary" data-action="whatsapp-birthday" data-id="${m.id}">Saludar ${icon('arrow',15)}</button></div>`).join('')||empty('Hoy no hay cumpleaños. Los próximos saludos aparecerán acá.')}<div class="info-box">${icon('message',20)}<p>Las campañas y los envíos automáticos requieren una integración con WhatsApp Business. Los recordatorios individuales ya están disponibles.</p></div></section></div>`;}

async function readFile(file,allowed,maxMb=2){if(!file||!file.size)return null;if(file.type==='application/pdf'){if(!allowed.includes('application/pdf'))throw new Error('El formato del archivo no está permitido. Usá JPG, PNG, WebP o PDF según el campo.');if(file.size>maxMb*1024*1024)throw new Error(`Cada archivo puede pesar hasta ${maxMb} MB.`);return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file);});}if(allowed.some(type=>type.startsWith('image/')))return imageDataUrl(file,maxMb*1024*1024);throw new Error('El formato del archivo no está permitido. Usá JPG, PNG, WebP o PDF según el campo.');}
function memberForm(id){const m=data().members.find(m=>m.id===id)||{};modal(id?'Editar ficha del socio':'Un nuevo comienzo',`<div class="form-intro"><span class="soft-icon peach">${icon('users',25)}</span><p>${id?'Mantené la información del socio actualizada.':'Completá la ficha. Después podrás registrar el pago de su primera membresía.'}</p></div><div class="form-grid">${field('Nombre y apellido *','name','text',m.name,'required maxlength="120" autocomplete="name"')}${field('DNI *','dni','text',m.dni,'required inputmode="numeric" pattern="[0-9]{5,12}" maxlength="12"')}${field('Fecha de nacimiento','birthDate','date',m.birthDate,`max="${data().today}"`)}${field('Teléfono','phone','tel',m.phone)}${field('WhatsApp (código de país incluido)','whatsapp','tel',m.whatsapp,'placeholder="54911…"')}${field('Email','email','email',m.email)}<div class="full">${field('Dirección','address','text',m.address)}</div>${field('Contacto de emergencia','emergencyName','text',m.emergencyName)}${field('Teléfono de emergencia','emergencyPhone','tel',m.emergencyPhone)}${field('Fecha de alta','joinedAt','date',m.joinedAt||data().today,'required')}${selectField('Estado del socio','state',[{value:'activo',label:'Activo (según su cuota)'},{value:'suspendido',label:'Suspendido'},{value:'baja',label:'Baja'}],m.state||'activo')}${field('Vencimiento del apto físico','medicalExpiresAt','date',m.medicalExpiresAt)}<label class="field"><span>Foto del socio · cámara o galería</span><input name="photoUpload" type="file" accept="image/*" capture="environment"></label><label class="field full"><span>Certificado médico · foto, galería o PDF</span><input name="medicalUpload" type="file" accept="image/*,application/pdf"></label><label class="field full"><span>Observaciones</span><textarea name="notes" rows="3" maxlength="3000">${esc(m.notes)}</textarea></label></div><p class="muted small">La membresía se activa al registrar un pago. La huella se podrá asociar cuando se integre un lector compatible.</p>`,async fd=>{const body=Object.fromEntries([...fd].filter(([key])=>!key.endsWith('Upload')));const photo=await readFile(fd.get('photoUpload'),['image/jpeg','image/png','image/webp']);const medical=await readFile(fd.get('medicalUpload'),['image/jpeg','image/png','image/webp','application/pdf'],4);if(photo)body.photo=photo;if(medical){body.medicalFile=medical;body.medicalFileName=fd.get('medicalUpload').name;}await api(`/api/members${id?'/'+id:''}`,{method:id?'PUT':'POST',body});toast(id?'Ficha actualizada.':'Socio registrado. Ya podés activar su membresía.');},true);}
function memberDetail(id){const m=data().members.find(m=>m.id===id);if(!m)return;const payments=byDate(data().payments.filter(p=>p.memberId===id));const checkins=byDate(data().checkins.filter(c=>c.memberId===id));const routines=data().routines.filter(r=>r.memberId===id);const measurements=byDate(data().measurements.filter(r=>r.memberId===id));modal('Ficha del socio',`<div class="member-detail-hero">${avatar(m)}<div><span class="eyebrow">SOCIO #${esc(m.number)}</span><h2>${esc(m.name)}</h2><p>${esc(m.planName||'Sin membresía')}</p>${statusBadge(m)}</div>${canDesk()?`<button class="btn btn-secondary" data-action="member-edit" data-id="${m.id}">${icon('edit',16)}Editar ficha</button>`:''}</div><div class="detail-grid">${[['DNI',m.dni],['Fecha de nacimiento',date(m.birthDate)],['Teléfono',m.phone],['WhatsApp',m.whatsapp],['Email',m.email],['Dirección',m.address],['Fecha de alta',date(m.joinedAt)],['Vencimiento',date(m.expiresAt)],['Último pago',date(m.lastPayment)],['Contacto de emergencia',`${m.emergencyName||'—'} ${m.emergencyPhone||''}`],['Apto físico',date(m.medicalExpiresAt)],['Último ingreso',date(m.lastCheckin)]].map(([t,v])=>`<div><span>${t}</span><strong>${esc(v||'—')}</strong></div>`).join('')}</div>${m.medicalFile?`<a href="${esc(m.medicalFile)}" download="${esc(m.medicalFileName||'certificado')}" class="btn btn-secondary">${icon('download',16)}Descargar certificado</a>`:''}${m.notes?`<div class="info-box"><p>${esc(m.notes)}</p></div>`:''}<div class="row-actions member-detail-actions">${canDesk()?`<button class="btn btn-primary" data-action="payment" data-id="${m.id}">${icon('wallet',17)}Registrar pago</button><button class="btn btn-secondary" data-action="whatsapp" data-id="${m.id}">${icon('message',17)}WhatsApp</button>`:''}<button class="btn btn-secondary" data-action="member-credential" data-id="${m.id}">${icon('qr',17)}Credencial</button></div>${financeRoles.includes(state.user.role)?`<h3 class="section-title">Historial de pagos</h3>${payments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Plan</th><th>Método</th><th>Importe</th></tr></thead><tbody>${payments.map(p=>`<tr><td>${date(p.date)}</td><td>${esc(data().plans.find(x=>x.id===p.planId)?.name||'Membresía')}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('Todavía no hay pagos registrados.')}`:''}<h3 class="section-title">Últimos ingresos</h3>${checkins.length?`<div class="mini-history">${checkins.slice(0,8).map(c=>`<div><span>${date(c.date)} · ${time(c.date)}</span>${badge(c.allowed?'Habilitado':'Denegado',c.allowed?'green':'red')}</div>`).join('')}</div>`:empty('Todavía no hay ingresos registrados.')}<h3 class="section-title">Rutinas</h3>${routines.map(r=>`<div class="routine-preview"><strong>${esc(r.name)}</strong><p class="muted">${esc(r.goal)}</p><pre>${esc(r.days)}</pre></div>`).join('')||'<p class="muted">Sin rutina asignada.</p>'}${measurements.length?`<h3 class="section-title">Progreso físico</h3><div class="mini-history">${measurements.slice(0,8).map(x=>`<div><span>${date(x.date)}</span><strong>${x.weight?`${esc(x.weight)} kg`:''} ${x.height?`· ${esc(x.height)} cm`:''}</strong></div>`).join('')}</div>`:''}`,null,true);}

function paymentForm(id){if(!data().cashSessions.some(s=>!s.closedAt)){modal('Primero, abrí la caja',`<div class="empty">${icon('wallet',40)}<h3>La caja está cerrada</h3><p>Registrá el efectivo inicial antes de cobrar cuotas o hacer ventas.</p><button class="btn btn-primary" data-action="go-cash">Ir a caja</button></div>`,null);return;}if(!data().members.length||!data().plans.some(p=>p.active!==false)){toast('Primero creá un socio y un plan activo.','error');return;}const selected=data().members.find(m=>m.id===id)||data().members[0];const plans=data().plans.filter(p=>p.active!==false);modal('Registrar un pago',`<div class="form-grid">${selectField('Socio','memberId',data().members.map(m=>({value:m.id,label:`${m.name} · #${m.number}`})),selected.id)}${selectField('Membresía','planId',plans.map(p=>({value:p.id,label:`${p.name} · ${money(p.price)}`})),selected.planId||plans[0].id)}${selectField('Medio de pago','method',['Efectivo','Transferencia','Mercado Pago','Débito','Crédito'].map(v=>({value:v,label:v})))}${isAdmin()?field('Descuento adicional (%)','discount','number',0,'min="0" max="100" step="1"'):'<input type="hidden" name="discount" value="0">'}</div><div id="payment-preview" class="payment-preview"></div><p class="muted small">La renovación se suma al vencimiento vigente si todavía está activo; si ya venció, comienza hoy.</p><span data-submit-label="Confirmar pago"></span>`,async fd=>{const body=Object.fromEntries(fd);body.discount=Number(body.discount);const result=await api('/api/payments',{method:'POST',body});toast(`Pago registrado. Vencimiento: ${date(result.member.expiresAt)}.`);});const form=document.getElementById('modal-form');const update=()=>{const m=data().members.find(m=>m.id===form.elements.memberId.value),p=plans.find(p=>p.id===form.elements.planId.value);const discount=Number(form.elements.discount.value)||0;const total=Math.round(p.price*(1-(p.discount||0)/100)*(1-discount/100));const expires=addDays(m.expiresAt&&m.expiresAt>data().today?m.expiresAt:data().today,p.duration);document.getElementById('payment-preview').innerHTML=`<span>Total a cobrar<strong>${money(total)}</strong></span><span>Nuevo vencimiento<strong>${date(expires)}</strong></span>`;};form.addEventListener('input',update);update();}

function whatsappDraft(id,type='recordatorio'){const m=data().members.find(m=>m.id===id);if(!m)return;modal(messageTemplates[type]||'Mensaje de WhatsApp',`<div class="member-inline">${avatar(m)}<strong>${esc(m.name)}</strong></div>${field('WhatsApp (código de país incluido)','phone','tel',m.whatsapp||m.phone,'required placeholder="54911…"')}<label class="field"><span>Mensaje</span><textarea name="message" rows="7" required>${esc(messageFor(m,type))}</textarea></label><p class="muted small">Se abrirá WhatsApp para que revises y envíes el mensaje.</p><span data-submit-label="Abrir WhatsApp"></span>`,fd=>{openWhatsApp(fd.get('phone'),fd.get('message'));});}
function openWhatsApp(phone,message){const normalized=String(phone||'').replace(/\D/g,'');if(normalized.length<10||normalized.length>15)throw new Error('Ingresá el número de WhatsApp con código de país, por ejemplo 54911…');window.open(`https://wa.me/${normalized}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');}

async function checkin(identifier,method='manual',override=false){const result=await api('/api/checkins',{method:'POST',body:{identifier,method,override}});accessResult=result;await refresh();clearTimeout(accessReset);accessReset=setTimeout(()=>{accessResult=null;if(state.route==='accesos')document.getElementById('access-result').innerHTML=accessResultHtml();},15000);return result;}
function bindPage(){document.getElementById('member-search')?.addEventListener('input',e=>{memberSearch=e.target.value;memberPage=0;document.getElementById('members-results').innerHTML=memberTable();});document.getElementById('chart-period')?.addEventListener('change',e=>{chartDays=Number(e.target.value);render();});document.getElementById('access-filter')?.addEventListener('change',e=>{accessFilter=e.target.value;render();});tickAccessClock();document.getElementById('access-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;try{await checkin(form.elements.identifier.value,form.elements.method.value);document.getElementById('access-identifier')?.focus();}catch(e){toast(e.message,'error');button.disabled=false;}});const mf=document.getElementById('message-form');if(mf){const update=()=>{const m=data().members.find(m=>m.id===mf.elements.memberId.value);communicationType=mf.elements.type.value;if(m)mf.elements.message.value=messageFor(m,communicationType);};mf.elements.memberId.addEventListener('change',update);mf.elements.type.addEventListener('change',update);mf.addEventListener('submit',e=>{e.preventDefault();try{const m=data().members.find(m=>m.id===mf.elements.memberId.value);if(!m)throw new Error('Elegí un socio.');openWhatsApp(m.whatsapp||m.phone,mf.elements.message.value);}catch(e){toast(e.message,'error');}});}}
function tickAccessClock(){const el=document.getElementById('access-clock');if(el)el.textContent=new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'America/Argentina/Buenos_Aires'});}
function credential(id){const m=data().members.find(m=>m.id===id);if(!m)return;modal('Credencial del socio',`<div class="credential"><div class="brand">${logo()}</div>${avatar(m)}<h2>${esc(m.name)}</h2><span>SOCIO #${esc(m.number)}</span><div class="credential-code" id="credential-qr"></div><p>DNI ${esc(m.dni)}</p><p class="muted small">Presentá tu DNI o número de socio en recepción.</p></div><details><summary>Código para lector QR</summary><p class="muted small">Token personal. El lector debe transmitir este texto en el campo de ingreso QR.</p><code class="token-code">${esc(m.qrToken||'No disponible')}</code></details><button class="btn btn-secondary" data-action="print-credential">${icon('download',16)}Imprimir credencial / PDF</button>`,null);if(m.qrToken)import('./qr.js').then(({qrSvg})=>{const el=document.getElementById('credential-qr');if(el)el.innerHTML=qrSvg(m.qrToken);}).catch(()=>{});}

async function action(name,id,element){switch(name){case 'modal-close':closeModal();break;case 'toggle-nav':document.body.classList.toggle('nav-open');break;case 'member-new':memberForm();break;case 'member-edit':memberForm(id);break;case 'member-detail':memberDetail(id);break;case 'member-credential':credential(id);break;case 'print-credential':window.print();break;case 'payment':paymentForm(id);break;case 'member-filter':memberFilter=id;memberPage=0;render();break;case 'member-prev':memberPage--;render();break;case 'member-next':memberPage++;render();break;case 'whatsapp':whatsappDraft(id);break;case 'whatsapp-recovery':whatsappDraft(id,'recuperacion');break;case 'whatsapp-birthday':whatsappDraft(id,'cumpleanos');break;case 'checkout':await api(`/api/checkins/${id}/checkout`,{method:'POST',body:{}});toast('Salida registrada.');await refresh();break;case 'access-override':confirmAction('Autorizar ingreso excepcional','Se registrará quién autorizó el ingreso con cuota vencida.',()=>checkin(id,'manual',true));break;case 'go-cash':closeModal();navigate('caja');break;case 'kiosk':document.body.classList.toggle('kiosk-mode');element.innerHTML=`${icon('fingerprint',18)}${document.body.classList.contains('kiosk-mode')?'Volver al panel':'Pantalla de recepción'}`;break;case 'alert-tab':dashboardAlert=id;render();break;case 'change-password':modal('Cambiar contraseña',`${field('Contraseña actual','currentPassword','password','','required minlength="8" autocomplete="current-password"')}${field('Nueva contraseña','newPassword','password','','required minlength="8" autocomplete="new-password"')}${field('Repetir nueva contraseña','confirmPassword','password','','required minlength="8" autocomplete="new-password"')}<span data-submit-label="Actualizar"></span>`,async fd=>{if(fd.get('newPassword')!==fd.get('confirmPassword'))throw new Error('Las contraseñas nuevas no coinciden.');await api('/api/password',{method:'POST',body:{currentPassword:fd.get('currentPassword'),newPassword:fd.get('newPassword')}});toast('Contraseña actualizada.');});break;case 'profile':modal('Tu sesión',`<div class="member-inline">${avatar(state.user)}<div><h3>${esc(state.user.name)}</h3><p class="muted">${esc(roles[state.user.role])} · ${esc(state.user.username)}</p></div></div><p class="muted">Tu usuario queda registrado en las operaciones que realizás.</p><div class="stack">${canDesk()?`<p class="muted small">Atajo: F2 abre el control de acceso.</p>`:''}<button class="btn btn-secondary" data-action="change-password">${icon('lock',18)}Cambiar contraseña</button><button class="btn btn-secondary" data-action="logout">${icon('logout',18)}Cerrar sesión</button></div>`,null);break;case 'logout':modal('Cerrar sesión',`<p>Vas a salir del sistema. Las demás pantallas siguen funcionando.</p><span data-submit-label="Cerrar sesión"></span>`,async()=>{await api('/api/logout',{method:'POST',body:{}});state.user=null;state.data=null;closeModal();await init();});break;default:await handleModuleAction(name,id,element);}}
document.addEventListener('click',async e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();navigate(route.dataset.route);return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;try{await action(el.dataset.action,el.dataset.id,el);}catch(error){toast(error.message,'error');}});
function render(){if(!state.user||!state.data)return;if(!pages[state.route]?.roles.includes(state.user.role))state.route='inicio';document.title=`${pages[state.route].title} · Anversol`;renderShell();}
document.addEventListener('app-render',render);
document.addEventListener('session-expired',()=>{closeModal();renderAuth(false);});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'inicio';render();});
function renderAuth(setup){document.body.classList.remove('kiosk-mode','nav-open');document.title='Bienvenido · Anversol';const access=state.access;document.getElementById('app').innerHTML=`<div class="auth-layout"><section class="auth-story"><a class="brand" href="/">${logo()}</a><div class="auth-story-content"><span class="eyebrow">MÁS QUE UN GIMNASIO. UNA COMUNIDAD.</span><h1>Cada día,<br>un poco<br><em>más fuertes.</em></h1><p>Vos acompañás sus objetivos.<br>Anversol se ocupa del resto.</p><div class="auth-art"><div class="art-orbit"></div><div class="art-orbit orbit-two"></div><div class="art-tile">${icon('dumbbell',75)}</div><span class="art-pill">${icon('heart',18)} El progreso se comparte.</span></div></div><div class="auth-story-footer">ANVERSOL GYM <span>Tu gimnasio, conectado.</span></div></section><section class="auth-form-area"><a class="auth-back" href="/">← Volver al sitio</a><span class="auth-local">${icon('shield',16)} Gestión local y privada</span><div class="auth-form-box"><div class="auth-mobile-brand">${logo()}</div><span class="soft-icon peach">${icon(setup?'sparkles':'sun',27)}</span><h2>${setup?'Hagamos lugar para crecer.':'Qué bueno verte de nuevo.'}</h2><p>${setup?'Configurá tu cuenta de dueño para comenzar.':'Ingresá a tu espacio de trabajo.'}</p><form id="auth-form">${setup?field('Tu nombre','name','text','','required autocomplete="name"'):''}${field('Usuario','username','text','','required autocomplete="username" maxlength="60"')}${field('Contraseña','password','password','','required minlength="8" autocomplete="'+(setup?'new-password':'current-password')+'"')}${setup?'<label class="checkbox-field"><input type="checkbox" name="demo"><span>Cargar datos de demostración<small>Socios y movimientos ficticios para recorrer el sistema. Dejalo desactivado para cargar socios reales.</small></span></label>':''}<div class="form-error" role="alert" hidden></div><button class="btn btn-primary full" type="submit">${setup?'Crear mi gimnasio':'Iniciar sesión'}${icon('arrow',18)}</button></form><div class="auth-note">${icon('wifi',18)}<span>Funciona en tu red local.<br>Incluso cuando no hay Internet.</span></div></div>${access?.lan?`<div class="auth-lan"><span class="eyebrow">DESDE EL CELULAR</span><p>Misma WiFi. Abrí esta dirección:</p><strong>${esc(access.url)}</strong><div class="auth-qr" id="auth-qr"></div><p class="muted small">Escaneá el código o escribí <em>anversol.local</em> en el navegador.</p></div>`:''}<span class="auth-copyright">Diseñado para moverte hacia adelante.</span></section></div>`;document.getElementById('auth-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,error=form.querySelector('.form-error'),button=form.querySelector('[type=submit]');error.hidden=true;button.disabled=true;const fd=new FormData(form);try{const body=Object.fromEntries(fd);if(setup)body.demo=fd.get('demo')==='on';const r=await api(setup?'/api/setup':'/api/login',{method:'POST',body});state.user=r.user;state.route='inicio';await refresh();}catch(e){error.textContent=e.message;error.hidden=false;button.disabled=false;}});if(access?.lan&&access.url)import('./qr.js').then(({qrSvg})=>{const el=document.getElementById('auth-qr');if(el)el.innerHTML=qrSvg(access.url,148);}).catch(()=>{});}
async function init(){try{const session=await api('/api/session');state.user=session.user;state.access=session.access||null;if(!session.user){renderAuth(session.needsSetup);return;}state.route=location.hash.slice(1)||'inicio';await refresh();}catch(e){document.getElementById('app').innerHTML=`<div class="initial-loading"><span class="soft-icon peach">${icon('wifi',32)}</span><h2>No pudimos conectar con el gimnasio</h2><p>${esc(e.message)}</p><button class="btn btn-primary" id="retry-connection">Volver a intentar</button></div>`;document.getElementById('retry-connection').addEventListener('click',init);}}
init();
// Refresh shared data without disturbing forms or focused inputs on other workstations.
setInterval(()=>{tickAccessClock();},1000);
setInterval(async()=>{if(!state.user||document.hidden||document.querySelector('.modal')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{await refresh();document.body.classList.remove('offline');}catch{document.body.classList.add('offline');}},45000);
document.addEventListener('keydown',e=>{if(e.key==='F2'&&state.user&&canDesk()&&!document.querySelector('[role=dialog]')){e.preventDefault();navigate('accesos');}});
